void add_suggestion_to_scene(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create UI components
    UiElement* icon = ui_element_create("icon");
    UiElement* content_text = ui_element_create("content_text");
    UiElement* description_text = ui_element_create("description_text");

    // Bind UI elements to model
    ui_element_bind(icon, model, "icon_property");
    ui_element_bind(content_text, model, "content_property");
    ui_element_bind(description_text, model, "description_property");

    // Create layout container
    UiElement* layout = ui_element_create("layout");
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content_text);
    ui_layout_add_child(layout, description_text);

    // Create and configure background button
    UiElement* background_button = ui_element_create("background_button");
    ui_element_set_property(background_button, "on_click", browser->navigate);
    ui_element_bind(background_button, model, "button_color_property");

    // Add the constructed element to the scene
    ui_scene_add_element(scene, background_button);

    // Set the binding to manage UI updates
    element_binding->update_callback = ui_element_update_from_model;
    element_binding->model = model;
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create and configure the background button
    UiElement* background_button = create_button_element();
    set_button_callback(background_button, (void*)browser, on_suggestion_click);

    // Create the layout container for the suggestion elements
    UiElement* layout = create_layout_element(HORIZONTAL);

    // Create and bind the icon element
    UiElement* icon = create_icon_element();
    bind_icon_model(icon, model, "icon_property");
    add_child(layout, icon);

    // Create and bind the content text element
    UiElement* content_text = create_text_element();
    bind_text_model(content_text, model, "content_property");
    add_child(layout, content_text);

    // Create and bind the description text element
    UiElement* description_text = create_text_element();
    bind_text_model(description_text, model, "description_property");
    add_child(layout, description_text);

    // Apply layout to the background button
    set_button_content(background_button, layout);

    // Bind button colors to the model
    bind_color_property(background_button, model, "background_color_property");

    // Bind the button to the SuggestionBinding
    bind_button_to_binding(background_button, element_binding);

    // Add the button to the scene
    add_element_to_scene(scene, background_button);
}

void create_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Construct icon, content text, and description text UI elements
    UiImage* icon = ui_image_create();
    UiText* content_text = ui_text_create();
    UiText* description_text = ui_text_create();

    // Bind UI elements to the model
    model_bind(icon, model, "icon_property");
    model_bind(content_text, model, "content_property");
    model_bind(description_text, model, "description_property");

    // Create a container layout to hold the suggestion UI
    UiLayout* layout = ui_layout_create();

    // Add icon, content, and description to the layout
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content_text);
    ui_layout_add_child(layout, description_text);

    // Create a background button for navigation
    UiButton* background_button = ui_button_create();
    ui_button_set_on_click(background_button, (void*)browser->navigate, NULL);

    // Bind button colors to the model
    model_bind(background_button, model, "button_color_property");

    // Add the layout as the content of the background button
    ui_button_set_content(background_button, layout);

    // Add the button to the scene
    ui_scene_add_element(scene, background_button);

    // Update binding object with relevant references
    element_binding->icon = icon;
    element_binding->content = content_text;
    element_binding->description = description_text;
    element_binding->button = background_button;
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Construct UI layout
    UiElement* layout = create_layout(HORIZONTAL);

    // Create and configure icon
    UiElement* icon = create_icon();
    bind_model_property(icon, "image", model, "icon_path");
    add_child(layout, icon);

    // Create and configure content text
    UiElement* content_text = create_text_label();
    bind_model_property(content_text, "text", model, "content");
    add_child(layout, content_text);

    // Create and configure description text
    UiElement* description_text = create_text_label();
    bind_model_property(description_text, "text", model, "description");
    add_child(layout, description_text);

    // Create background button and bind color to model
    UiElement* background_button = create_button();
    bind_model_property(background_button, "background_color", model, "button_color");

    // Set up navigation on click
    set_on_click(background_button, (OnCallback)navigate_to_suggestion, browser);

    // Add the suggestion element to the scene
    add_child_to_scene(scene, background_button);

    // Finalize binding setup
    initialize_binding(element_binding, model, layout);
}

void create_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    UiElement* layout = ui_layout_create(UI_LAYOUT_VERTICAL);

    UiElement* icon = ui_icon_create();
    ui_element_bind_property(icon, "image", model, "icon_url");
    ui_layout_add_child(layout, icon);

    UiElement* content_text = ui_text_create();
    ui_element_set_property(content_text, "font_size", 18);
    ui_element_bind_property(content_text, "text", model, "content");
    ui_layout_add_child(layout, content_text);

    UiElement* description_text = ui_text_create();
    ui_element_set_property(description_text, "font_size", 14);
    ui_element_bind_property(description_text, "text", model, "description");
    ui_layout_add_child(layout, description_text);

    UiElement* background_button = ui_button_create();
    ui_element_bind_property(background_button, "background_color", model, "background_color");
    ui_element_bind_property(background_button, "hover_color", model, "hover_color");
    ui_element_bind_property(background_button, "active_color", model, "active_color");
    ui_element_set_property(background_button, "cursor", "pointer");

    ui_element_set_click_handler(background_button, (UiClickHandler)ui_browser_navigate, browser, model);
    ui_element_add_child(background_button, layout);

    ui_scene_add_element(scene, background_button);

    element_binding->element = background_button;
    element_binding->model = model;
}
